  // the definitions that WOULD have applied here, had anyone written them down
  var missing = sqlgen_attach(sqlgen_Q_COUNT);
  var f = [];
  var gates = sqlgen_gates({
    parses: true, kind: "Select", tables: ["customers"], cols: 2, est: sqlgen_ROWS_TOTAL
  });

