  var withSem = r.picked.concat(semT);
  var keptSem = sqlgen_ctxTok(withSem.length);
  var f = [];
  var gates = sqlgen_gates({
    parses: true, kind: "Select", tables: ["customers"], cols: 4, est: sqlgen_ROWS_TOTAL
  });

